import {hospitals,resources,seedRequests,distance} from './seed.js';
const $=(s,root=document)=>root.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=20)=>{const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',hospital:'M4 21V5h16v16 M2 21h20 M9 21v-5h6v5 M9 8h6 M12 5v6',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M18 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',send:'M22 2L9 15 M22 2l-7 20-6-7-7-6z',check:'M5 12l4 4L19 6',pulse:'M2 12h5l3-8 4 16 3-8h5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',close:'M6 6l12 12 M6 18L18 6',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h1 M3 12h1 M3 18h1',external:'M14 3h7v7 M21 3l-9 9 M10 3H3v18h18v-7'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.hospital).split(' M').map((p,i)=>`<path d="${i?'M':''}${p}"/>`).join('')}</svg>`;};
let current='cedar',view='dashboard',tab='all',query='',status='All statuses',requests=structuredClone(seedRequests),selected=null;
const hospital=id=>hospitals.find(h=>h.id===id),me=()=>hospital(current);
const matches=(req)=>hospitals.filter(h=>h.id!==req.hospitalId&&h.resources.includes(req.resource)&&distance(hospital(req.hospitalId),h)<=req.radiusKm);
const incoming=r=>r.hospitalId!==current&&matches(r).some(h=>h.id===current);
const relevant=r=>r.hospitalId===current||incoming(r);
const age=r=>{const m=Math.max(0,Math.floor((Date.now()-r.createdAt)/60000));return m<60?`${m} min ago`:`${Math.floor(m/60)} hr ago`;};
function notify(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function render(){
const local=requests.filter(relevant),active=local.filter(r=>r.status!=='Completed'),incomingCount=local.filter(r=>incoming(r)&&r.status==='Awaiting responses').length;
$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="Hospital Connect dashboard"><span class="brandmark">${icon('plus',26)}</span><span>Hospital<span class="brand-light">Connect</span></span></a><div class="workspace-label">COORDINATION WORKSPACE</div><nav aria-label="Main navigation"><button class="nav-item ${view==='dashboard'?'active':''}" data-nav="dashboard" data-testid="dashboard-nav">${icon('grid')}<span>Dashboard</span></button><button class="nav-item ${view==='requests'?'active':''}" data-nav="requests" data-testid="requests-nav">${icon('list')}<span>My requests</span><small>${requests.filter(r=>r.hospitalId===current&&r.status!=='Completed').length}</small></button><button class="nav-item ${view==='hospitals'?'active':''}" data-nav="hospitals" data-testid="hospitals-nav">${icon('hospital')}<span>Hospital network</span></button></nav><div class="sidebar-bottom"><div class="network-health"><span class="dot"></span> Sample network active</div><div class="sidebar-help">Better connected.<br><strong>Better care.</strong><p>Find the right resources,<br>when they’re needed.</p></div><div class="profile"><span class="avatar">CV</span><span>Demo coordinator<small>Sample workspace</small></span><span class="demo-mini">DEMO</span></div></div></aside>
<div class="shell"><header class="topbar"><div class="breadcrumb">Workspace <span>/</span> <strong>${view==='hospitals'?'Hospital network':view==='requests'?'My requests':'Dashboard'}</strong></div><div class="hospital-select">${icon('hospital',18)}<label class="sr-only" for="hospital-switch">Active hospital</label><select id="hospital-switch" data-testid="hospital-switch">${hospitals.map(h=>`<option value="${h.id}" ${current===h.id?'selected':''}>${esc(h.name)}</option>`).join('')}</select><span class="avatar small">${me().short.split(' ').map(w=>w[0]).slice(0,2).join('')}</span></div></header>
<main><div class="demo-banner" data-testid="demo-banner"><span>${icon('pulse',17)} <strong>You’re exploring a demo</strong> <span class="banner-description">Fictional hospitals. Requests reset on refresh. No real alerts or patient data.</span></span><span class="sample-pill">SAMPLE DATA</span></div>
<div class="page-heading"><div><div class="eyebrow">HOSPITAL RESOURCE COORDINATION</div><h1>${view==='hospitals'?'Your connected network':view==='requests'?'Your hospital’s requests':'The right care starts here.'}</h1><p>${view==='hospitals'?'Explore nearby hospitals and the resources they can offer.':'A clear view of what’s needed, and who can help.'}</p></div><button class="primary" id="new-request" data-testid="new-request">${icon('plus',18)} New request</button></div>
${view==='hospitals'?directory():`<section class="stats" aria-label="Network overview"><article><span class="stat-label">Active requests ${icon('send',18)}</span><strong>${active.length}<small>in your network</small></strong><span class="stat-foot">${local.filter(r=>r.hospitalId===current&&r.status!=='Completed').length} sent by your hospital</span></article><article><span class="stat-label">Incoming requests ${icon('bell',18)}</span><strong>${incomingCount}<small>need a response</small></strong><span class="stat-foot amber">A chance to make a difference</span></article><article><span class="stat-label">Hospitals nearby ${icon('hospital',18)}</span><strong>${hospitals.filter(h=>h.id!==current&&distance(me(),h)<=100).length}<small>within 100 km</small></strong><span class="stat-foot teal">Connected through shared resources</span></article><article><span class="stat-label">Completed requests ${icon('check',18)}</span><strong>${local.filter(r=>r.status==='Completed').length}<small>in this demo</small></strong><span class="stat-foot">Every connection counts</span></article></section><div class="dashboard-grid"><section class="panel request-panel"><div class="panel-heading"><div><h2>${view==='requests'?'My requests':'Resource requests'} <span class="count">${local.length}</span></h2><p>Coordinate resources, one connection at a time.</p></div><span class="live-label"><span class="dot"></span> Demo activity</span></div><div class="tabs" role="group" aria-label="Request view"><button data-tab="all" class="${tab==='all'?'selected':''}" data-testid="all-tab">All requests</button><button data-tab="sent" class="${tab==='sent'?'selected':''}" data-testid="sent-tab">Sent by us</button><button data-tab="incoming" class="${tab==='incoming'?'selected':''}" data-testid="incoming-tab">Incoming <span>${incomingCount}</span></button></div><div class="filters"><div class="searchbox">${icon('search',17)}<input id="request-search" data-testid="request-search" placeholder="Search resource or hospital…" aria-label="Search requests" value="${esc(query)}"></div><select id="status-filter" data-testid="status-filter" aria-label="Filter by status">${['All statuses','Awaiting responses','Accepted','Completed'].map(s=>`<option ${status===s?'selected':''}>${s}</option>`).join('')}</select></div><div id="request-list" data-testid="request-list">${requestList()}</div><div class="panel-footer">${icon('check',14)} Availability is confirmed by the responding hospital before travel.</div></section><aside class="right-column">${networkPanel()}<section class="connection-card"><span class="connection-icon">${icon('pulse',25)}</span><h3>A connection can change<br>someone’s day.</h3><p>Your hospital’s resources could be exactly what a nearby community needs.</p><button class="text-button" id="help-incoming">View incoming requests ${icon('arrow',17)}</button></section><div class="privacy-note">${icon('check',15)} Built around hospital coordination.<br>No patient details in this demo.</div></aside></div>`}<footer class="site-footer"><span>Hospital Connect <span>·</span> Bringing care within reach.</span><span>Interactive prototype · Fictional data</span></footer></main></div>`;
bind();}
function requestList(){const rows=requests.filter(relevant).filter(r=>(view!=='requests'||r.hospitalId===current)&&(tab!=='sent'||r.hospitalId===current)&&(tab!=='incoming'||incoming(r))&&(status==='All statuses'||r.status===status)&&(`${r.resource} ${hospital(r.hospitalId).name} ${r.id}`.toLowerCase().includes(query.toLowerCase())));return rows.length?rows.map(r=>`<button class="request-row" data-request="${r.id}" data-testid="request-${r.id}"><span class="resource-icon ${r.urgency==='Critical'?'critical-icon':''}">${icon(r.resource.includes('bed')?'hospital':'pulse',23)}</span><span class="request-body"><span class="row-title">${esc(r.resource)} <span class="badge ${r.urgency.toLowerCase()}">${r.urgency}</span></span><span class="hospital-name">${esc(hospital(r.hospitalId).name)}</span><span class="row-meta"><span>${icon('pin',12)} ${r.radiusKm} km radius</span><span>${icon('clock',12)} ${age(r)}</span>${r.hospitalId===current?'<span class="sent-label">Sent by us</span>':''}</span></span><span class="request-end"><span class="status ${r.status==='Accepted'?'accepted':r.status==='Completed'?'completed':''}"><span class="status-dot"></span>${r.status}</span><span class="responses ${r.responses.length?'has-responses':''}">${r.responses.length?`${r.responses.length} response${r.responses.length>1?'s':''}`:'No responses yet'} ${icon('arrow',15)}</span></span></button>`).join(''):`<div class="empty" data-testid="empty-requests">${icon('search',30)}<h3>No requests found</h3><p>Try another search, status, or request view.</p></div>`;}
function networkPanel(){const nearby=hospitals.filter(h=>h.id!==current&&distance(me(),h)<=100).sort((a,b)=>distance(me(),a)-distance(me(),b));return `<section class="panel network-panel"><div class="panel-heading"><div><h2>Nearby hospitals</h2><p>${icon('pin',12)} Within 100 km of your hospital</p></div></div><div class="network-map" aria-label="Illustration of the sample hospital network"><svg viewBox="0 0 320 140" aria-hidden="true"><defs><pattern id="mapgrid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#dce7e1" stroke-width=".7"/></pattern></defs><rect width="320" height="140" fill="url(#mapgrid)"/><path d="M0 100Q70 40 120 80T320 50" fill="none" stroke="#c1dfdf" stroke-width="13"/><path d="M0 100Q70 40 120 80T320 50" fill="none" stroke="#e1f0ed" stroke-width="8"/><circle cx="160" cy="70" r="55" fill="#0b7b7010" stroke="#0b7b7050" stroke-dasharray="4 4"/><path d="M160 70L99 39M160 70L224 36M160 70L246 112M160 70L102 115" stroke="#7cae9d" stroke-dasharray="3 4"/><g fill="#fff" stroke="#66a38a" stroke-width="2"><circle cx="99" cy="39" r="6"/><circle cx="224" cy="36" r="6"/><circle cx="246" cy="112" r="6"/><circle cx="102" cy="115" r="6"/></g><circle cx="160" cy="70" r="14" fill="#0d6e61"/><path d="M154 70h12M160 64v12" stroke="white" stroke-width="2"/><text x="12" y="130" font-size="9" fill="#748b83">SAMPLE NETWORK · NOT A ROAD MAP</text></svg></div>${nearby.slice(0,3).map(h=>`<div class="nearby-row"><span class="mini-hospital">${icon('hospital',19)}</span><span><strong>${esc(h.short)}</strong><small>${esc(h.resources.slice(0,2).join(' · '))}</small></span><span class="distance">${Math.round(distance(me(),h))} km</span></div>`).join('')}<button class="network-link" id="view-network">View hospital network ${icon('arrow',16)}</button></section>`;}
function directory(){const rows=hospitals.filter(h=>`${h.name} ${h.resources.join(' ')}`.toLowerCase().includes(query.toLowerCase()));return `<section class="panel directory"><div class="panel-heading"><div><h2>Hospital network <span class="count">${hospitals.length}</span></h2><p>Sample resources for exploring the coordination workflow.</p></div><div class="searchbox">${icon('search',17)}<input id="directory-search" data-testid="directory-search" placeholder="Find a hospital or resource…" aria-label="Search hospital network" value="${esc(query)}"></div></div><div id="directory-results" class="hospital-grid" data-testid="directory-results">${directoryCards(rows)}</div></section>`;}
function directoryCards(rows){return rows.length?rows.map(h=>`<article class="hospital-card" data-testid="hospital-card-${h.id}"><span class="directory-icon">${icon('hospital',25)}</span><div class="hospital-card-top"><h3>${esc(h.name)}</h3><span class="badge routine">${h.id===current?'Your hospital':`${Math.round(distance(me(),h))} km away`}</span></div><p>${icon('pin',14)} ${esc(h.town)} · Fictional facility</p><div class="resource-tags">${h.resources.map(r=>`<span>${esc(r)}</span>`).join('')}</div><small>Sample coordination contact</small><p class="contact">${esc(h.contact)}</p><button class="secondary switch-hospital" data-hospital="${h.id}">Explore as this hospital ${icon('arrow',15)}</button></article>`).join(''):'<div class="empty"><h3>No matching hospitals</h3><p>Try another hospital name or resource.</p></div>';}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;tab=view==='requests'?'sent':'all';query='';status='All statuses';render();});$('.brand').onclick=e=>{e.preventDefault();view='dashboard';tab='all';query='';render();};$('#hospital-switch').onchange=e=>{current=e.target.value;query='';render();};$('#new-request').onclick=openRequest;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});document.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>openDetail(b.dataset.request));const search=$('#request-search');if(search)search.oninput=e=>{query=e.target.value;$('#request-list').innerHTML=requestList();document.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>openDetail(b.dataset.request));};const sf=$('#status-filter');if(sf)sf.onchange=e=>{status=e.target.value;render();};if($('#view-network'))$('#view-network').onclick=()=>{view='hospitals';query='';render();};if($('#help-incoming'))$('#help-incoming').onclick=()=>{tab='incoming';query='';status='Awaiting responses';render();};const ds=$('#directory-search');if(ds)ds.oninput=e=>{query=e.target.value;$('#directory-results').innerHTML=directoryCards(hospitals.filter(h=>`${h.name} ${h.resources.join(' ')}`.toLowerCase().includes(query.toLowerCase())));bindSwitches();};bindSwitches();}
function bindSwitches(){document.querySelectorAll('[data-hospital]').forEach(b=>b.onclick=()=>{current=b.dataset.hospital;view='dashboard';query='';tab='all';render();notify(`Exploring as ${me().short}`);});}
function openRequest(){const modal=$('#request-modal');modal.innerHTML=`<form id="new-request-form"><div class="modal-header"><span class="modal-icon">${icon('send',24)}</span><button type="button" class="icon-button close-modal" aria-label="Close new request">${icon('close')}</button></div><div class="eyebrow">REACH YOUR NETWORK</div><h2 id="modal-title">Create a resource request</h2><p class="modal-description">Find a nearby hospital that can help ${esc(me().short)}.</p><label for="resource">Resource needed</label><select id="resource" name="resource" data-testid="resource">${resources.map(r=>`<option>${r}</option>`).join('')}</select><div class="form-grid"><div><label for="urgency">Urgency</label><select id="urgency" name="urgency" data-testid="urgency"><option>Routine</option><option selected>Urgent</option><option>Critical</option></select></div><div><label for="radius">Search radius (km)</label><input type="number" id="radius" name="radius" min="1" max="500" step="1" value="100" required data-testid="radius"></div></div><label for="note">Coordination note <span class="optional">optional</span></label><textarea id="note" name="note" maxlength="500" rows="3" placeholder="Resource or timing details only. No patient information." data-testid="note"></textarea><div class="match-preview" id="match-preview" data-testid="match-preview"></div><div class="demo-form-note">Sample request only. No notifications will be sent.</div><div class="modal-actions"><button type="button" class="secondary close-modal">Cancel</button><button class="primary" type="submit" data-testid="send-request">${icon('send',16)} Send demo request</button></div></form>`;modal.querySelectorAll('.close-modal').forEach(b=>b.onclick=()=>modal.close());const update=()=>{const radius=Number($('#radius').value),resource=$('#resource').value;const matched=matches({hospitalId:current,radiusKm:radius,resource});$('#match-preview').innerHTML=`${icon('hospital',18)}<div><strong>${matched.length} matching hospital${matched.length===1?'':'s'}</strong><span>${matched.length?matched.map(h=>`${esc(h.short)} (${Math.round(distance(me(),h))} km)`).join(' · '):'No matching hospitals within this radius. Try a wider search.'}</span></div>`;};$('#resource').onchange=update;$('#radius').oninput=update;update();$('#new-request-form').onsubmit=e=>{e.preventDefault();const radius=Number($('#radius').value);if(!Number.isInteger(radius)||radius<1||radius>500||!resources.includes($('#resource').value))return;const id=`HC-${Math.max(...requests.map(r=>Number(r.id.split('-')[1])))+1}`;requests.unshift({id,hospitalId:current,resource:$('#resource').value,urgency:$('#urgency').value,radiusKm:radius,note:$('#note').value.trim(),createdAt:Date.now(),status:'Awaiting responses',responses:[]});view='dashboard';tab='sent';query='';status='All statuses';modal.close();render();notify(`${id} created · ${matches(requests[0]).length} sample hospitals match`);};modal.showModal();}
function openDetail(id){selected=id;const r=requests.find(r=>r.id===id),own=r.hospitalId===current,modal=$('#detail-modal'),offered=r.responses.some(x=>x.hospitalId===current);modal.innerHTML=`<div class="modal-header"><span class="eyebrow">${r.id} · SAMPLE REQUEST</span><button class="icon-button" id="close-detail" aria-label="Close request details">${icon('close')}</button></div><h2 id="detail-title">${esc(r.resource)} request</h2><p class="modal-description">${esc(hospital(r.hospitalId).name)}</p><div class="detail-badges"><span class="badge ${r.urgency.toLowerCase()}">${r.urgency}</span><span class="status">${r.status}</span><span class="badge routine">${r.radiusKm} km radius</span></div><section class="detail-section"><h3>Coordination note</h3><p class="note-content" data-testid="detail-note">${esc(r.note||'No additional coordination details.')}</p></section>${r.acceptedHospitalId?`<div class="destination" data-testid="destination">${icon('check',20)}<div><strong>${r.status==='Completed'?'Completed with':'Accepted destination'}</strong><p>${esc(hospital(r.acceptedHospitalId).name)}</p><small>${esc(hospital(r.acceptedHospitalId).contact)}</small></div></div>`:''}<section class="detail-section"><h3>Hospital responses <span class="count">${r.responses.length}</span></h3>${r.responses.length?r.responses.map(x=>`<div class="response-card"><span class="mini-hospital">${icon('hospital',21)}</span><div><strong>${esc(hospital(x.hospitalId).name)}</strong><p>Available in ${x.availabilityMinutes} minutes · ${Math.round(distance(hospital(r.hospitalId),hospital(x.hospitalId)))} km</p><small>${esc(hospital(x.hospitalId).contact)}</small></div>${own&&r.status==='Awaiting responses'?`<button class="secondary accept-response" data-accept="${x.hospitalId}" data-testid="accept-${x.hospitalId}">Accept</button>`:''}</div>`).join(''):'<p class="muted">No responses yet. Switch to a matching sample hospital to offer availability.</p>'}</section>${!own&&incoming(r)&&r.status==='Awaiting responses'?offered?'<div class="destination" data-testid="offer-confirmation">Your hospital has responded to this request.</div>':`<form id="offer-form" class="offer-form"><h3>Can your hospital help?</h3><p>Offer an estimated availability time for ${esc(me().short)}.</p><label for="availability">Available in (minutes)</label><div class="offer-input"><input id="availability" type="number" min="1" max="10080" step="1" required value="30" data-testid="availability"><button class="primary" data-testid="offer-availability">Offer availability</button></div></form>`:''}${own&&r.status==='Accepted'?'<button class="primary full" id="complete-request" data-testid="complete-request">Mark request completed</button>':''}<div class="demo-form-note">Confirm clinical suitability and arrangements directly before travel. Demo only.</div>`;$('#close-detail').onclick=()=>modal.close();modal.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>{if(r.hospitalId!==current||r.status!=='Awaiting responses')return;r.acceptedHospitalId=b.dataset.accept;r.status='Accepted';render();openDetail(id);notify('Response accepted. Coordinate directly with the receiving hospital.');});const offer=$('#offer-form');if(offer)offer.onsubmit=e=>{e.preventDefault();const minutes=Number($('#availability').value);if(!Number.isInteger(minutes)||minutes<1||minutes>10080||r.status!=='Awaiting responses'||!incoming(r)||r.responses.some(x=>x.hospitalId===current))return;r.responses.push({hospitalId:current,availabilityMinutes:minutes});render();openDetail(id);notify('Your sample availability response has been added.');};if($('#complete-request'))$('#complete-request').onclick=()=>{if(r.hospitalId!==current||r.status!=='Accepted')return;r.status='Completed';render();openDetail(id);notify('Request marked completed.');};if(!modal.open)modal.showModal();}
for(const modal of document.querySelectorAll('dialog'))modal.addEventListener('click',e=>{if(e.target===modal){const box=modal.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)modal.close();}});
render();
